import React, { useState, useEffect } from 'react';
import {
  Typography, Box, Button, CircularProgress, Alert, IconButton
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import Brightness4Icon from '@mui/icons-material/Brightness4';
import Brightness7Icon from '@mui/icons-material/Brightness7';
import StatsCards from './StatsCards';
import InventoryTable from './InventoryTable';
import AddEditInventoryDialog from './AddEditInventoryDialog';
import { getInventoryItems, deleteInventoryItem } from '../../api/inventoryApi';

const AdminInventoryContent = () => {
  const [inventory, setInventory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [openDialog, setOpenDialog] = useState(false);
  const [itemToEdit, setItemToEdit] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  const fetchItems = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await getInventoryItems();
      setInventory(response.data);
    } catch (err) {
      console.error("Failed to fetch inventory items:", err);
      setError('Failed to fetch inventory items.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchItems();
  }, []);

  const handleOpenDialog = (item = null) => {
    setItemToEdit(item);
    setOpenDialog(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this item?')) {
      try {
        await deleteInventoryItem(id);
        fetchItems();
      } catch (err) {
        console.error("Failed to delete inventory item:", err);
        setError(err.response?.data?.message || 'Failed to delete inventory item.');
      }
    }
  };

  const filteredInventory = inventory.filter(item =>
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.partId.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <Box display="flex" justifyContent="center" mt={4}><CircularProgress /></Box>;

  return (
    <Box>
      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h5" sx={{ color: 'text.primary', fontWeight: 600 }}>
          Inventory Dashboard
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => handleOpenDialog()}
          sx={{
            bgcolor: 'primary.main',
            '&:hover': { bgcolor: 'primary.dark' }
          }}
        >
          ADD NEW ITEM
        </Button>
      </Box>

      <StatsCards inventory={inventory} />
      
      <Box mt={4}>
        <InventoryTable
          inventory={filteredInventory}
          searchTerm={searchTerm}
          setSearchTerm={setSearchTerm}
          onEdit={handleOpenDialog}
          onDelete={handleDelete}
        />
      </Box>

      <AddEditInventoryDialog
        open={openDialog}
        onClose={() => setOpenDialog(false)}
        item={itemToEdit}
        onSave={fetchItems}
      />
    </Box>
  );
};

export default AdminInventoryContent;