import React, { useState, useEffect } from 'react';
import {
  Typography, Box, Button, CircularProgress, Alert
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import { getSuppliers, deleteSupplier } from '../../api/supplierApi';
import DataTable from '../DataTable';
import AddEditSupplierDialog from './AddEditSupplierDialog';

const AdminSupplierContent = () => {
  const [suppliers, setSuppliers] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [supplierToEdit, setSupplierToEdit] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  const fetchSuppliers = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await getSuppliers();
      setSuppliers(response.data);
    } catch (err) {
      console.error("Failed to fetch suppliers:", err);
      setError('Failed to fetch suppliers.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSuppliers();
  }, []);

  const handleOpenDialog = (supplier = null) => {
    setSupplierToEdit(supplier);
    setOpenDialog(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this supplier?')) {
      try {
        await deleteSupplier(id);
        fetchSuppliers();
      } catch (err) {
        console.error("Failed to delete supplier:", err);
        setError(err.response?.data?.message || 'Failed to delete supplier.');
      }
    }
  };

  const columns = [
    { id: 'supplierId', label: 'Supplier ID', minWidth: 100 },
    { id: 'name', label: 'Name', minWidth: 170 },
    { id: 'phone', label: 'Phone', minWidth: 130 },
    { id: 'email', label: 'Email', minWidth: 200 },
    { id: 'actions', label: 'Actions', minWidth: 120, align: 'right' },
  ];

  const filteredSuppliers = suppliers.filter(supplier =>
    supplier.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    supplier.supplierId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <Box display="flex" justifyContent="center" mt={4}><CircularProgress /></Box>;

  return (
    <Box>
      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h5" sx={{ color: 'text.primary', fontWeight: 600 }}>
          Supplier List
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => handleOpenDialog()}
          sx={{
            bgcolor: 'primary.main',
            '&:hover': { bgcolor: 'primary.dark' }
          }}
        >
          ADD SUPPLIER
        </Button>
      </Box>

      <DataTable
        columns={columns}
        data={filteredSuppliers}
        searchTerm={searchTerm}
        setSearchTerm={setSearchTerm}
        onEdit={handleOpenDialog}
        onDelete={handleDelete}
        searchPlaceholder="Search by name or ID..."
      />

      <AddEditSupplierDialog
        open={openDialog}
        onClose={() => setOpenDialog(false)}
        supplier={supplierToEdit}
        onSave={fetchSuppliers}
      />
    </Box>
  );
};

export default AdminSupplierContent;