import React, { useState, useEffect } from 'react';
import {
  Typography, Box, Button, CircularProgress, Alert, ButtonGroup,
  TableContainer, Paper, Table, TableHead, TableRow, TableCell, TableBody,
  TextField, MenuItem, Select, FormControl, InputLabel
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import DescriptionIcon from '@mui/icons-material/Description';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { getStockMovements, deleteStockMovement } from '../../api/stockApi';
import AddStockInForm from './AddStockInForm';
import AddStockOutForm from './AddStockOutForm';

const AdminStockContent = () => {
  const [stockMovements, setStockMovements] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [openInDialog, setOpenInDialog] = useState(false);
  const [openOutDialog, setOpenOutDialog] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [dateFilter, setDateFilter] = useState('all');

  const fetchStockMovements = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await getStockMovements();
      setStockMovements(response.data);
    } catch (err) {
      console.error("Failed to fetch stock movements:", err);
      setError('Failed to fetch stock movements.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStockMovements();
  }, []);

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this stock movement?')) {
      try {
        await deleteStockMovement(id);
        fetchStockMovements();
      } catch (err) {
        console.error("Failed to delete stock movement:", err);
        setError(err.response?.data?.message || 'Failed to delete stock movement.');
      }
    }
  };

  const generateReport = async () => {
    setIsGenerating(true);
    try {
      const doc = new jsPDF();
      
      // Title
      doc.setFontSize(20);
      doc.text('Stock Movement Report', 20, 20);
      
      // Date
      doc.setFontSize(12);
      doc.text(`Generated on: ${new Date().toLocaleDateString()}`, 20, 35);
      
      // Table
      const tableData = filteredMovements.map(movement => [
        movement.itemId,
        movement.itemName,
        movement.type,
        movement.quantity,
        movement.reason,
        new Date(movement.date).toLocaleDateString()
      ]);
      
      doc.autoTable({
        head: [['Item ID', 'Item Name', 'Type', 'Quantity', 'Reason', 'Date']],
        body: tableData,
        startY: 45,
      });
      
      doc.save('stock-movement-report.pdf');
    } catch (err) {
      console.error("Failed to generate report:", err);
      setError('Failed to generate report.');
    } finally {
      setIsGenerating(false);
    }
  };

  const filterByDate = (movements) => {
    if (dateFilter === 'all') return movements;
    
    const now = new Date();
    const filterDate = new Date();
    
    switch (dateFilter) {
      case 'today':
        filterDate.setHours(0, 0, 0, 0);
        return movements.filter(m => new Date(m.date) >= filterDate);
      case 'week':
        filterDate.setDate(now.getDate() - 7);
        return movements.filter(m => new Date(m.date) >= filterDate);
      case 'month':
        filterDate.setMonth(now.getMonth() - 1);
        return movements.filter(m => new Date(m.date) >= filterDate);
      default:
        return movements;
    }
  };

  const filteredMovements = filterByDate(
    stockMovements.filter(movement =>
      movement.itemName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      movement.itemId.toLowerCase().includes(searchTerm.toLowerCase()) ||
      movement.type.toLowerCase().includes(searchTerm.toLowerCase())
    )
  );

  if (loading) return <Box display="flex" justifyContent="center" mt={4}><CircularProgress /></Box>;

  return (
    <Box>
      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h5" sx={{ color: 'text.primary', fontWeight: 600 }}>
          Stock Movement Management
        </Typography>
        <Box display="flex" gap={1}>
          <Button
            variant="outlined"
            startIcon={<DescriptionIcon />}
            onClick={generateReport}
            disabled={isGenerating}
            sx={{ color: 'text.primary', borderColor: 'primary.main' }}
          >
            {isGenerating ? 'Generating...' : 'Generate Report'}
          </Button>
          <ButtonGroup variant="contained">
            <Button
              startIcon={<AddIcon />}
              onClick={() => setOpenInDialog(true)}
              sx={{ bgcolor: 'success.main', '&:hover': { bgcolor: 'success.dark' } }}
            >
              Stock In
            </Button>
            <Button
              startIcon={<AddIcon />}
              onClick={() => setOpenOutDialog(true)}
              sx={{ bgcolor: 'error.main', '&:hover': { bgcolor: 'error.dark' } }}
            >
              Stock Out
            </Button>
          </ButtonGroup>
        </Box>
      </Box>

      <Box display="flex" gap={2} mb={3}>
        <TextField
          label="Search stock movements..."
          variant="outlined"
          size="small"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          sx={{ flexGrow: 1 }}
        />
        <FormControl size="small" sx={{ minWidth: 120 }}>
          <InputLabel>Date Filter</InputLabel>
          <Select
            value={dateFilter}
            label="Date Filter"
            onChange={(e) => setDateFilter(e.target.value)}
          >
            <MenuItem value="all">All Time</MenuItem>
            <MenuItem value="today">Today</MenuItem>
            <MenuItem value="week">Last Week</MenuItem>
            <MenuItem value="month">Last Month</MenuItem>
          </Select>
        </FormControl>
      </Box>

      <TableContainer component={Paper} sx={{ bgcolor: 'background.paper' }}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Item ID</TableCell>
              <TableCell>Item Name</TableCell>
              <TableCell>Type</TableCell>
              <TableCell align="right">Quantity</TableCell>
              <TableCell>Reason</TableCell>
              <TableCell>Date</TableCell>
              <TableCell align="center">Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {filteredMovements.map((movement) => (
              <TableRow key={movement._id} hover>
                <TableCell>{movement.itemId}</TableCell>
                <TableCell>{movement.itemName}</TableCell>
                <TableCell>
                  <Box
                    component="span"
                    sx={{
                      px: 1,
                      py: 0.5,
                      borderRadius: 1,
                      color: 'white',
                      bgcolor: movement.type === 'in' ? 'success.main' : 'error.main',
                      fontSize: '0.875rem'
                    }}
                  >
                    {movement.type.toUpperCase()}
                  </Box>
                </TableCell>
                <TableCell align="right">{movement.quantity}</TableCell>
                <TableCell>{movement.reason}</TableCell>
                <TableCell>{new Date(movement.date).toLocaleDateString()}</TableCell>
                <TableCell align="center">
                  <Button
                    variant="outlined"
                    color="error"
                    size="small"
                    onClick={() => handleDelete(movement._id)}
                  >
                    Delete
                  </Button>
                </TableCell>
              </TableRow>
            ))}
            {filteredMovements.length === 0 && (
              <TableRow>
                <TableCell colSpan={7} align="center" sx={{ py: 4 }}>
                  <Typography color="text.secondary">
                    No stock movements found.
                  </Typography>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <AddStockInForm
        open={openInDialog}
        onClose={() => setOpenInDialog(false)}
        onSave={fetchStockMovements}
      />

      <AddStockOutForm
        open={openOutDialog}
        onClose={() => setOpenOutDialog(false)}
        onSave={fetchStockMovements}
      />
    </Box>
  );
};

export default AdminStockContent;