import React, { useState } from 'react';
import {
  Box,
  Container,
  Typography,
  Tabs,
  Tab,
  Paper,
  createTheme,
  ThemeProvider
} from '@mui/material';
import {
  Inventory,
  People,
  Storage
} from '@mui/icons-material';
import AdminHeader from '../../components/AdminHeader';
import AdminFooter from '../../components/AdminFooter';
import AdminInventoryContent from '../../components/InventoryCom/AdminInventoryContent';
import AdminSupplierContent from '../../components/InventoryCom/AdminSupplierContent';
import AdminStockContent from '../../components/InventoryCom/AdminStockContent';

// Dark theme for admin pages
const darkTheme = createTheme({
  palette: {
    mode: 'dark',
    primary: {
      main: '#6366f1',
    },
    secondary: {
      main: '#a855f7',
    },
    background: {
      default: '#0f172a',
      paper: '#1e293b',
    },
    text: {
      primary: '#f8fafc',
      secondary: '#e2e8f0',
    },
  },
});

function TabPanel({ children, value, index, ...other }) {
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`inventory-tabpanel-${index}`}
      aria-labelledby={`inventory-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ py: 3 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

function a11yProps(index) {
  return {
    id: `inventory-tab-${index}`,
    'aria-controls': `inventory-tabpanel-${index}`,
  };
}

const AdminInventoryManagement = () => {
  const [value, setValue] = useState(0);

  const handleChange = (event, newValue) => {
    setValue(newValue);
  };

  return (
    <ThemeProvider theme={darkTheme}>
      <Box sx={{ minHeight: '100vh', bgcolor: 'background.default' }}>
        <AdminHeader />
        
        <Container maxWidth="xl" sx={{ py: 4 }}>
          <Typography
            variant="h3"
            sx={{
              textAlign: 'center',
              fontWeight: 800,
              mb: 4,
              background: 'linear-gradient(90deg, #6366f1, #a855f7)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
            }}
          >
            🏭 Inventory Management
          </Typography>

          <Paper
            elevation={3}
            sx={{
              borderRadius: 3,
              overflow: 'hidden',
              background: 'linear-gradient(135deg, #1e293b 0%, #334155 100%)',
              border: '1px solid rgba(99,102,241,0.3)',
            }}
          >
            <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
              <Tabs
                value={value}
                onChange={handleChange}
                centered
                sx={{
                  '& .MuiTab-root': {
                    color: 'text.secondary',
                    fontWeight: 600,
                    fontSize: '1rem',
                    minWidth: 200,
                    py: 2,
                    '&.Mui-selected': {
                      color: 'primary.main',
                    },
                  },
                  '& .MuiTabs-indicator': {
                    backgroundColor: 'primary.main',
                    height: 3,
                  },
                }}
              >
                <Tab
                  icon={<Inventory />}
                  label="Inventory Items"
                  {...a11yProps(0)}
                  sx={{ iconStyle: { mb: 1 } }}
                />
                <Tab
                  icon={<People />}
                  label="Suppliers"
                  {...a11yProps(1)}
                  sx={{ iconStyle: { mb: 1 } }}
                />
                <Tab
                  icon={<Storage />}
                  label="Stock Management"
                  {...a11yProps(2)}
                  sx={{ iconStyle: { mb: 1 } }}
                />
              </Tabs>
            </Box>

            <TabPanel value={value} index={0}>
              <AdminInventoryContent />
            </TabPanel>
            <TabPanel value={value} index={1}>
              <AdminSupplierContent />
            </TabPanel>
            <TabPanel value={value} index={2}>
              <AdminStockContent />
            </TabPanel>
          </Paper>
        </Container>

        <AdminFooter />
      </Box>
    </ThemeProvider>
  );
};

export default AdminInventoryManagement;